        // Include the final endpoint exactly.
        if (k == m - 1) {
            y_interpolated[k] = y[n - 1];
            continue;
        }

        const double x = static_cast<double>(k) * (n - 1) / (m - 1);
        const int i = static_cast<int>(x);
        const double fraction = x - i;

        // Original x coordinates are integers spaced one unit apart.
        y_interpolated[k] = y[i] + fraction * (y[i + 1] - y[i]);
    }

    std::cout.precision(8);
