            self.app.notify(f"Selected: {self.path.name}")
            return

        if event.button.has_class("delete"):
            try:
                self.path.unlink()
            except OSError as exc:
                self.app.notify(f"Could not delete: {exc}", severity="error")
            else:
                self.app.notify(f"Deleted: {self.path.name}")
                await self.remove()


class FileApp(App):
    BINDINGS = [("q", "quit", "Quit")]

    CSS = """
    #files {
        height: 1fr;
        padding: 1;
    }
    """

    def __init__(self, directory: Path) -> None:
        super().__init__()
        self.directory = directory

    def compose(self) -> ComposeResult:
        with VerticalScroll(id="files"):
            files = sorted(
                (p for p in self.directory.iterdir() if p.is_file()),
                key=lambda p: p.name.lower(),
            )
            if not files:
                yield Static("No files found.")
            for path in files:
                yield FileRow(path)

        yield Footer()


if __name__ == "__main__":
