            },
        );

        match result {
            Ok(mut watcher) => {
                match watcher.watch(&input, RecursiveMode::NonRecursive) {
                    Ok(()) => {
                        self.log.push(format!("Watching {}", input.display()));
                        self.events = Some(rx);
