## My answer to the prompt

Find the connected components formed by the existing roads. For each component, choose its cheapest house. Then connect every other component’s cheapest house to the globally cheapest house.

### Why this is optimal

Let there be \(k\) components, with minimum house prices \(b_1,\ldots,b_k\), and let \(b_s\) be the smallest.

Because all road prices are positive, an optimal solution connects the components with a tree of \(k-1\) new roads. Root any such tree at component \(s\). For every other component \(i\), its edge to its parent costs at least
\[
b_i+b_s,
\]
because its endpoint in component \(i\) costs at least \(b_i\), and its other endpoint costs at least the global minimum \(b_s\).

Connecting each component directly to the globally cheapest house achieves this lower bound for every component, so the resulting star is optimal.

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, sz;

    DSU(int n) : parent(n + 1), sz(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int v) {
        if (parent[v] == v) return v;
        return parent[v] = find(parent[v]);
    }

    void unite(int u, int v) {
        u = find(u);
        v = find(v);
        if (u == v) return;

        if (sz[u] < sz[v]) swap(u, v);
        parent[v] = u;
        sz[u] += sz[v];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<long long> a(n + 1);
    int center = 1;

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        if (a[i] < a[center]) center = i;
    }

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }

    vector<int> cheapest(n + 1, -1);
    for (int i = 1; i <= n; ++i) {
        int root = dsu.find(i);
        if (cheapest[root] == -1 || a[i] < a[cheapest[root]]) {
            cheapest[root] = i;
        }
    }

    int centerRoot = dsu.find(center);
    vector<pair<int, int>> roads;

    for (int root = 1; root <= n; ++root) {
        if (cheapest[root] != -1 && root != centerRoot) {
            roads.emplace_back(center, cheapest[root]);
        }
    }

    cout << roads.size() << '\n';
    for (auto [u, v] : roads) {
        cout << u << ' ' << v << '\n';
    }
}
```

**Complexity:** \(O((n+m)\alpha(n))\) time and \(O(n)\) additional space. If the city is already connected, the program prints `0`.

