import SwiftUI

enum PointKind: String, CaseIterable, Identifiable {
    case unspecified = "Not specified"
    case winner = "Winner"
    case unforcedError = "Unforced error"
    case forcedError = "Forced error"
    case ace = "Ace"
    case returnWinner = "Return winner"
    case serveWinner = "Serve winner"

    var id: String { rawValue }
}

struct PointEntry: Identifiable {
    let id = UUID()
    let player: Int
    let kind: PointKind
    let location: String
}

struct Match {
    var games = [0, 0]
    var points = [0, 0]
    var setsWon = [0, 0]
    var completedSets: [[Int]] = []
    var winner: Int?
    var history: [PointEntry] = []

    var isTiebreak: Bool { games == [6, 6] }

    func pointLabel(_ player: Int) -> String {
        guard winner == nil else { return "–" }
        if isTiebreak { return "\(points[player])" }

        let own = points[player]
        let other = points[1 - player]

        if own >= 3 && other >= 3 {
            return own > other ? "AD" : "40"
        }
        return ["0", "15", "30", "40"][min(own, 3)]
    }

    var pointScore: String {
        if isTiebreak {
            return "Tiebreak \(points[0])–\(points[1])"
        }
        if points[0] >= 3 && points[0] == points[1] {
            return "Deuce"
        }
        return "\(pointLabel(0))–\(pointLabel(1))"
    }

    mutating func awardPoint(to player: Int, kind: PointKind) {
        guard winner == nil, (0...1).contains(player) else { return }

        let opponent = 1 - player
        let playingTiebreak = isTiebreak
        let gameDescription = playingTiebreak
            ? "Tiebreak"
            : "Game \(games[0] + games[1] + 1)"

        history.append(PointEntry(
            player: player,
            kind: kind,
            location: """
            Set \(completedSets.count + 1), \(gameDescription), \
            before point: \(pointScore)
            """
        ))

        points[player] += 1

        let target = playingTiebreak ? 7 : 4
        guard points[player] >= target,
              points[player] - points[opponent] >= 2 else { return }

        // A completed tiebreak adds the seventh game to its winner.
        games[player] += 1
        points = [0, 0]

        let setFinished = playingTiebreak ||
            (games[player] >= 6 && games[player] - games[opponent] >= 2)

        guard setFinished else { return }

        completedSets.append(games)
        setsWon[player] += 1
        games = [0, 0]

        if setsWon[player] == 2 {
            winner = player
        }
    }
}

