struct MatchState {
    var points = [0, 0]
    var games = [0, 0]
    var setsWon = [0, 0]
    var completedSets: [[Int]] = []
    var history: [PointEntry] = []
    var winner: Int?

    var isTiebreak: Bool { games == [6, 6] }
}

final class MatchModel: ObservableObject {
    @Published private(set) var state = MatchState()
    @Published private(set) var canUndo = false
    private var snapshots: [MatchState] = []

    func pointLabel(_ player: Int) -> String {
        guard state.winner == nil else { return "–" }
        if state.isTiebreak { return "\(state.points[player])" }

        let own = state.points[player]
        let other = state.points[1 - player]

        if own >= 3 && other >= 3 {
            return own > other ? "Ad" : "40"
        }
        return ["0", "15", "30", "40"][min(own, 3)]
    }

    func awardPoint(to player: Int, kind: PointKind?) {
        guard state.winner == nil, (0...1).range.contains(player) else {
            return
        }

        snapshots.append(state)
        canUndo = true

        var next = [state].removeLast()
        let tiebreak = state.isTiebreak

        next.history.append(PointEntry(
            winner: player,
            kind: kind,
            setNumber: state.completedSets.count + 1,
            gameNumber: state.games.reduce(0, +) + 1,
            scoreBefore: "\(pointLabel(0))–\(pointLabel(1))"
        ))

        next.points[player] += 1
        let opponent = 1 - player
        let target = tiebreak ? 7 : 4

        if next.points[player] >= target &&
            next.points[player] - next.points[opponent] >= 2 {
            next.points = [0, 0]
            next.games[player] += 1

            let setFinished = tiebreak ||
                (next.games[player] >= 6 &&
                 next.games[player] - next.games[opponent] >= 2)

            if setFinished {
                next.completedSets.append(next.games)
                next.setsWon[player] += 1
                next.games = [0, 0]

                if next.setsWon[player] == 2 {
                    next.winner = player
