const METHODS = ["FindPosition", "detectObjects", "classifyImage"];
const pretty = (value) => JSON.stringify(value, null, 2);

const ApiMethodPanel = ({ apiPrefix }) => {
  const [method, setMethod] = useState(METHODS[0]);
  const [body, setBody] = useState("{}");
  const [response, setResponse] = useState("");
  const [lastRequest, setLastRequest] = useState(null);
  const [status, setStatus] = useState("");
  const [busy, setBusy] = useState(false);

  const requestUrl = (name) => `/api/${apiPrefix}/${name}`;

  const post = async (url, text, isMock = false) => {
    // Keep validation errors separate from network errors.
    let payload;
    try {
      payload = pretty(JSON.parse(text));
    } catch (error) {
      setStatus(`Invalid JSON: ${error.message}`);
      return;
    }

    setBusy(true);
    setStatus("");
    setLastRequest({ url, body: payload });

    try {
      const result = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: payload,
      });

      const raw = await result.text();
      let formatted = raw;
      try {
        formatted = pretty(JSON.parse(raw));
      } catch {
        // Preserve non-JSON responses for debugging.
      }

      if (!isMock) setResponse(formatted);

      setStatus(
        result.ok
          ? isMock
            ? "Mock response saved."
            : `HTTP ${result.status}`
          : `HTTP ${result.status}: ${formatted}`
      );
    } catch (error) {
      setStatus(`Request failed: ${error.message}`);
    } finally {
      setBusy(false);
    }
  };

  return html`
    <div class="panel">
      <div class="panel-header">
        <h4 class="panel-title">POST API Tester</h4>
      </div>
      <div class="panel-body">
        <div style="display:flex; flex-wrap:wrap;">
          ${METHODS.map((name) => html`
            <button
              key=${name}
              class=${`btn ${method === name ? "btn-primary" : ""}`}
              disabled=${busy}
              onClick=${() => {
                setMethod(name);
                setResponse("");
                post(requestUrl(name), body);
              }}>
              ${name}
            </button>
          `)}
        </div>

        <div class="form-group">
          <label class="form-label">Request URL</label>
          <pre class="code">POST ${requestUrl(method)}</pre>
        </div>

        <div class="form-group">
          <label class="form-label">Request JSON — editable</label>
          <textarea
            class="form-input"
            rows="8"
            spellcheck="false"
            value=${body}
            onInput=${(event) => setBody(event.target.value)}
          ></textarea>
        </div>

        <button
          class="btn btn-primary"
          disabled=${busy}
          onClick=${() => post(requestUrl(method), body)}>
          Send Again
        </button>

        <div class="form-group">
          <label class="form-label">Response JSON — editable</label>
          <textarea
            class="form-input"
            rows="10"
            spellcheck="false"
            value=${response}
            onInput=${(event) => setResponse(event.target.value)}
          ></textarea>
        </div>

        <button
          class="btn"
          disabled=${busy || !response.trim()}
          onClick=${() =>
            post(
              `/api/setresponse/${apiPrefix}/${method}`,
              response,
              true
            )}>
          Set Mock Response
        </button>

        <div role="status">${status}</div>

        ${lastRequest && html`
          <details>
            <summary>Last POST request</summary>
            <pre class="code">POST ${lastRequest.url}</pre>
            <pre class="code" data-lang="JSON">${lastRequest.body}</pre>
          </details>
        `}
      </div>
    </div>
  `;
};
```

