          <details>
            <summary>Last sent request</summary>
            <pre class="code">${`POST ${lastRequest.url}\n\n${lastRequest.body}`}</pre>
          </details>
        `}

        <label class="form-label" for=${`${apiPrefix}-response`}>
          Response JSON — edit to configure the mock
        </label>
        <textarea
          id=${`${apiPrefix}-response`}
          class="form-input"
          rows="10"
          spellcheck="false"
          disabled=${busy}
          value=${responseBody}
          onInput=${(e) => setResponseBody(e.target.value)}></textarea>

        <button
          class="btn btn-primary"
          disabled=${busy || !responseBody.trim()}
          onClick=${setMockResponse}>
          Set Mock Response
        </button>

        <pre role="status" aria-live="polite">${status}</pre>
      </div>
    </div>
  `;
};
```

Replace the duplicated `Vision1Page` and `Vision2Page` with:

