fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    controllerState: []const i16,
) !void {
    const event_count = @intFromEnum(ControllerEvents.START) + 1;

    if (controllerState.len != event_count)
        return error.InvalidControllerState;

    var packet: [event_count * 4]u8 = undefined;

    for (controllerState, 0..) |value, index| {
        const event_index: u16 = @intCast(index);
        const value_bits: u16 = @bitCast(value);
        const offset = index * 4;

        packet[offset] = @truncate(event_index);
        packet[offset + 1] = @truncate(event_index >> 8);
        packet[offset + 2] = @truncate(value_bits);
        packet[offset + 3] = @truncate(value_bits >> 8);
    }

    const sent = try posix.sendto(
        sock,
        packet[0..],
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len)
        return error.IncompleteDatagram;
}
```

