        std.mem.writeInt(
            u16,
            packet[offset..][0..2],
            @intCast(index),
            .little,
        );
        std.mem.writeInt(
            i16,
            packet[offset + 2 ..][0..2],
            value,
            .little,
        );
    }

    const sent = try posix.sendto(
        sock,
        packet[0..],
        0,
        &addr.any,
        addr.getOsSockLen(),
    );

    if (sent != packet.len) {
