For a self-contained byte array, you cannot meaningfully copy a `HashSet<string>`’s raw memory: it contains references to other managed objects, not inline string data. Instead, define an explicit binary format.

Here is a low-level, span-based example for .NET 6+:

```csharp
#nullable enable

using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Text;

public static class StringSetSerializer
{
    // Reject invalid UTF-16 rather than silently replacing characters.
    private static readonly Encoding Utf8 =
        new UTF8Encoding(false, true);

    // Format, all integers little-endian:
    // int32 item count
    // For each item:
    //   int32 UTF-8 byte length (-1 means null)
    //   byte[length] UTF-8 data
    public static byte[] ToBytes(HashSet<string> set)
    {
        ArgumentNullException.ThrowIfNull(set);

        // Do not modify the set concurrently while taking this snapshot.
        var items = new string[set.Count];
        set.CopyTo(items);

        int size = 4;
        foreach (string? item in items)
        {
            size = checked(size + 4);
            if (item is not null)
                size = checked(size + Utf8.GetByteCount(item));
        }

        var result = new byte[size];
        BinaryPrimitives.WriteInt32LittleEndian(
            result.AsSpan(), items.Length);

        int offset = 4;
        foreach (string? item in items)
        {
            int length = item is null ? -1 : Utf8.GetByteCount(item);

            BinaryPrimitives.WriteInt32LittleEndian(
                result.AsSpan(offset, 4), length);
            offset += 4;

            if (item is not null)
            {
                offset += Utf8.GetBytes(
                    item.AsSpan(), result.AsSpan(offset, length));
            }
        }

        return result;
    }
}
```

Usage:

```csharp
var set = new HashSet<string> { "apple", "banana" };
byte[] bytes = StringSetSerializer.ToBytes(set);
```

This serializes **contents, not internal buckets or the equality comparer**. A reader must use the same format and the intended comparer. Enumeration order is unspecified; sort the snapshot with `StringComparer.Ordinal` if you need stable ordering for identical stored strings. If arbitrary UTF-16 code units must round-trip, including unpaired surrogates, use an explicit UTF-16-code-unit format instead.

