## My answer to the user prompt

Use **MVVM with an injected recording service**:

- The service owns `AVAudioRecorder`, audio-session configuration, and files.
- The view model owns recording state and level sampling.
- SwiftUI displays a centered, audio-reactive visualization and Start/Stop buttons.

The visualization below is an **amplitude meter styled like an equalizer**, not a frequency-spectrum analyzer. That matches an “equalizer-like effect” without requiring FFT processing.

This example targets **iOS 17+** and saves AAC recordings permanently in the app’s Documents directory.

### 1. Microphone permission

Add this to the app target’s Info settings or `Info.plist`:

```xml
<key>NSMicrophoneUsageDescription</key>
<string>Record your voice and save recordings on this device.</string>
```

### 2. Recording service

```swift
import AVFoundation
import Foundation

@MainActor
protocol RecordingService: AnyObject {
    func requestPermission() async -> Bool
    func start() throws
    func stop() -> URL?
    func level() -> Float
}

enum RecordingError: LocalizedError {
    case startFailed

    var errorDescription: String? {
        "The recording could not be started."
    }
}

@MainActor
final class AudioRecordingService: RecordingService {
    private var recorder: AVAudioRecorder?
    private var fileURL: URL?

    func requestPermission() async -> Bool {
        await AVAudioApplication.requestRecordPermission()
    }

    func start() throws {
        guard recorder == nil else { return }

        let session = AVAudioSession.sharedInstance()
        let directory = FileManager.default.urls(
            for: .documentDirectory,
            in: .userDomainMask
        )[0]

        let url = directory
            .appendingPathComponent(UUID().uuidString)
            .appendingPathExtension("m4a")

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let candidate = try AVAudioRecorder(
                url: url,
                settings: settings
            )

            candidate.isMeteringEnabled = true

            guard candidate.prepareToRecord(), candidate.record() else {
                candidate.stop()
                throw RecordingError.startFailed
            }

            recorder = candidate
            fileURL = url
        } catch {
            try? FileManager.default.removeItem(at: url)
            deactivateSession()
            throw error
        }
    }

    func stop() -> URL? {
        guard let recorder else { return nil }

        // Do not require recorder.isRecording: an interruption may already
        // have stopped recording, but we still need to release resources.
        recorder.stop()

        let finishedURL = fileURL
        self.recorder = nil
        fileURL = nil
        deactivateSession()

        return finishedURL
    }

    func level() -> Float {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let decibels = recorder.averagePower(forChannel: 0)
        guard decibels.isFinite else { return 0 }

        // Display-oriented mapping: -50 dB -> 0, 0 dB -> 1.
        return min(max((decibels + 50) / 50, 0), 1)
    }

    private func deactivateSession() {
        try? AVAudioSession.sharedInstance().setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }
}
```

### 3. View model

The `preparing` state prevents repeated Start taps while permission is pending. The request identifier prevents an outstanding permission request from starting recording after the screen disappears.

```swift
import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    enum State {
        case idle
        case preparing
        case recording
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels =
        Array(repeating: Float(0), count: 24)
    @Published private(set) var savedURL: URL?
    @Published var errorMessage: String?

    private let service: any RecordingService
    private var meterTask: Task<Void, Never>?
    private var pendingRequest: UUID?
    private var smoothedLevel: Float = 0

    init(service: any RecordingService) {
        self.service = service
    }

    func start() async {
        guard state == .idle else { return }

        let request = UUID()
        pendingRequest = request
        state = .preparing
        errorMessage = nil

        let allowed = await service.requestPermission()

        guard pendingRequest == request else { return }
        pendingRequest = nil

        guard allowed else {
            state = .idle
            errorMessage =
                "Microphone access is disabled. Enable it in Settings."
            return
        }

        do {
            try service.start()
            savedURL = nil
            smoothedLevel = 0
            state = .recording
            startMetering()
        } catch {
            state = .idle
            errorMessage = error.localizedDescription
        }
    }

    func stop() {
        pendingRequest = nil
        meterTask?.cancel()
        meterTask = nil

        if let url = service.stop() {
            savedURL = url
        }

        state = .idle
        smoothedLevel = 0
        levels = Array(repeating: 0, count: levels.count)
    }

    private func startMetering() {
        meterTask?.cancel()

        meterTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard self != nil else { return }
                self?.sample()

                do {
                    try await Task.sleep(for: .milliseconds(50))
                } catch {
                    return
                }
            }
        }
    }

    private func sample() {
        smoothedLevel += (service.level() - smoothedLevel) * 0.3

        // A short history makes a waveform-like animated bar display,
        // without generating random values during SwiftUI rendering.
        levels.removeFirst()
        levels.append(smoothedLevel)
    }

    deinit {
        meterTask?.cancel()
    }
}
```

### 4. SwiftUI screen

This implementation deliberately finishes recording when the view disappears, the app leaves the foreground, or an audio interruption begins. Background recording would require a different lifecycle policy and additional configuration.

```swift
import AVFoundation
import SwiftUI

struct RecordingMeter: View {
    let levels: [Float]

    var body: some View {
        GeometryReader { geometry in
            HStack(alignment: .center, spacing: 3) {
                ForEach(levels.indices, id: \.self) { index in
                    Capsule()
                        .fill(.blue.gradient)
                        .frame(maxWidth: .infinity)
                        .frame(
                            height: max(
                                5,
                                CGFloat(levels[index]) * geometry.size.height
                            )
                        )
                }
            }
            .frame(
                width: geometry.size.width,
                height: geometry.size.height
            )
        }
        .animation(.easeOut(duration: 0.08), value: levels)
        .accessibilityLabel("Recording audio level")
    }
}

@MainActor
struct VoiceRecorderView: View {
    @Environment(\.scenePhase) private var scenePhase
    @StateObject private var model: RecorderViewModel

    init(service: any RecordingService = AudioRecordingService()) {
        _model = StateObject(
            wrappedValue: RecorderViewModel(service: service)
        )
    }

    var body: some View {
        VStack(spacing: 24) {
            Text(title)
                .font(.title2.bold())

            Spacer()

            RecordingMeter(levels: model.levels)
                .frame(height: 140)

            Spacer()

            if let url = model.savedURL {
                Text("Saved: \(url.lastPathComponent)")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
                    .lineLimit(2)
            }

            HStack(spacing: 20) {
                Button {
                    Task { await model.start() }
                } label: {
                    Label("Start", systemImage: "mic.fill")
                        .frame(maxWidth: .infinity)
                }
                .disabled(model.state != .idle)

                Button {
                    model.stop()
                } label: {
                    Label("Stop", systemImage: "stop.fill")
                        .frame(maxWidth: .infinity)
                }
                .disabled(model.state != .recording)
            }
            .buttonStyle(.borderedProminent)
        }
        .padding(24)
        .alert(
            "Recording Error",
            isPresented: Binding(
                get: { model.errorMessage != nil },
                set: { if !$0 { model.errorMessage = nil } }
            )
        ) {
            Button("OK", role: .cancel) {
                model.errorMessage = nil
            }
        } message: {
            Text(model.errorMessage ?? "")
        }
        .onDisappear {
            model.stop()
        }
        .onChange(of: scenePhase) { _, phase in
            if phase != .active {
                model.stop()
            }
        }
        .onReceive(
            NotificationCenter.default.publisher(
                for: AVAudioSession.interruptionNotification
            )
        ) { notification in
            guard
                let raw = notification.userInfo?[
                    AVAudioSessionInterruptionTypeKey
                ] as? UInt,
                AVAudioSession.InterruptionType(rawValue: raw) == .began
            else { return }

            model.stop()
        }
    }

    private var title: String {
        switch model.state {
        case .idle: "Voice Recorder"
        case .preparing: "Requesting microphone access…"
        case .recording: "Recording…"
        }
    }
}
```

Present `VoiceRecorderView()` from the existing app’s `WindowGroup`; do not add a second `@main` app type.

For a shipping application, also implement recorder-delegate error reporting and media-services-reset recovery, and test permission denial, interruptions, low storage, and repeated recordings on a physical device. The service protocol provides the injection point for automated state-transition tests.

