Without this key, requesting microphone access terminates the app.

### 2. Recording service

```swift
// AudioRecordingService.swift

import AVFoundation
import Foundation

@MainActor
protocol AudioRecordingService: AnyObject {
    func requestPermission() async -> Bool
    func start() throws
    func stop() -> URL?
    func readLevel() -> Float
}

enum RecordingError: LocalizedError {
    case couldNotStart

    var errorDescription: String? {
        "The microphone recording could not be started."
    }
}

@MainActor
final class AVAudioRecordingService: AudioRecordingService {
    private let session = AVAudioSession.sharedInstance()
    private var recorder: AVAudioRecorder?

    func requestPermission() async -> Bool {
        await AVAudioApplication.requestRecordPermission()
    }

    func start() throws {
        guard recorder == nil else { return }

        let directory = try FileManager.default.url(
            for: .documentDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        let url = directory.appendingPathComponent(
            "Voice-\(UUID().uuidString).m4a"
        )

        do {
            try session.setCategory(.record, mode: .default)
            try session.setActive(true)

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100.0,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let candidate = try AVAudioRecorder(
                url: url,
                settings: settings
            )
            candidate.isMeteringEnabled = true

            guard candidate.prepareToRecord(), candidate.record() else {
                candidate.stop()
                throw RecordingError.couldNotStart
            }

            recorder = candidate
        } catch {
            try? FileManager.default.removeItem(at: url)
            deactivateSession()
            throw error
        }
    }

    func stop() -> URL? {
        guard let recorder else { return nil }

        let url = recorder.url
        recorder.stop()
        self.recorder = nil
        deactivateSession()
        return url
    }

    func readLevel() -> Float {
        guard let recorder, recorder.isRecording else { return 0 }

        recorder.updateMeters()
        let decibels = recorder.averagePower(forChannel: 0)
        guard decibels.isFinite else { return 0 }

        // A display-oriented mapping, not a physical amplitude measurement.
        return min(max((decibels + 60) / 60, 0), 1)
    }

    private func deactivateSession() {
        try? session.setActive(
            false,
            options: .notifyOthersOnDeactivation
        )
    }
}
```

A UUID avoids overwriting files when recordings start close together. Documents provides persistent app-local storage, unlike the temporary directory.

### 3. View model

```swift
// RecorderViewModel.swift

import Combine
import Foundation

@MainActor
final class RecorderViewModel: ObservableObject {
    enum State {
        case idle
        case requestingPermission
        case recording
        case finished(URL)
    }

    @Published private(set) var state: State = .idle
    @Published private(set) var levels: [Float] =
        Array(repeating: 0, count: 24)
    @Published var errorMessage: String?

    private let service: any AudioRecordingService
    private var meterTask: Task<Void, Never>?
    private var requestID = UUID()
    private var smoothedLevel: Float = 0

    init(service: any AudioRecordingService) {
        self.service = service
    }

    var isRecording: Bool {
        if case .recording = state { return true }
        return false
    }

    var isRequestingPermission: Bool {
        if case .requestingPermission = state { return true }
        return false
    }

    var savedURL: URL? {
        if case .finished(let url) = state { return url }
        return nil
    }

    func start() async {
        guard !isRecording, !isRequestingPermission else { return }

        let previousState = state
        let id = UUID()
        requestID = id
        state = .requestingPermission
        errorMessage = nil

        let allowed = await service.requestPermission()

        // Do not start if the screen disappeared or stop() was called
        // while permission was being requested.
        guard requestID == id else { return }
        guard !Task.isCancelled else {
            state = previousState
            return
        }

        guard allowed else {
            state = previousState
            errorMessage =
                "Microphone access is disabled. Enable it in Settings."
            return
        }

        do {
            try service.start()
            smoothedLevel = 0
            levels = Array(repeating: 0, count: levels.count)
            state = .recording
            beginMetering()
        } catch {
            state = previousState
            errorMessage = error.localizedDescription
        }
    }

    func stop() {
        requestID = UUID()
        meterTask?.cancel()
        meterTask = nil

        if isRecording {
            if let url = service.stop() {
                state = .finished(url)
            } else {
                state = .idle
                errorMessage = "No recording was available to save."
            }
        } else if isRequestingPermission {
            state = .idle
        }

        levels = Array(repeating: 0, count: levels.count)
    }

    private func beginMetering() {
        meterTask?.cancel()
        meterTask = Task { @MainActor [weak self] in
            while !Task.isCancelled {
                guard self?.isRecording == true else { return }
                self?.sample()

                do {
                    try await Task.sleep(for: .milliseconds(50))
                } catch {
                    return
                }
            }
        }
    }

    private func sample() {
        let rawLevel = service.readLevel()
        smoothedLevel += (rawLevel - smoothedLevel) * 0.3

        var next = levels
        next.removeFirst()
        next.append(smoothedLevel)
        levels = next
    }

    deinit {
        meterTask?.cancel()
    }
}
```

The permission-requesting state prevents rapid taps from starting overlapping recordings. The request identifier prevents recording from unexpectedly starting after the user has left the screen.

