using boost::multiprecision::cpp_int;

cpp_int readScore() {
    string s;
    cin >> s;

    cpp_int value = 0;
    for (char c : s) {
        value *= 10;
        value += c - '0';
    }
    return value;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    cpp_int sum1 = 0, sum2 = 0;

    for (int i = 0; i < n; ++i)
        sum1 += readScore();

    for (int i = 0; i < n; ++i)
        sum2 += readScore();

    cout << (sum1 > sum2 ? "one" : "two") << '\n';
    return 0;
}
```

