### My answer

Since scores can approach \(10^{100}\), even `long long` is insufficient. Store scores and totals as decimal strings, add digit by digit, and compare the totals.

```cpp
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

string add(const string& a, const string& b) {
    int i = static_cast<int>(a.size()) - 1;
    int j = static_cast<int>(b.size()) - 1;
    int carry = 0;
    string result;

    while (i >= 0 || j >= 0 || carry) {
        int digit = carry;
        if (i >= 0) digit += a[i--] - '0';
        if (j >= 0) digit += b[j--] - '0';

        result.push_back(char('0' + digit % 10));
        carry = digit / 10;
    }

    reverse(result.begin(), result.end());

    // Remove leading zeros so length-based comparison is valid.
    size_t first = result.find_first_not_of('0');
    return first == string::npos ? "0" : result.substr(first);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    string total1 = "0", total2 = "0", score;

    for (int i = 0; i < n; ++i) {
        cin >> score;
        total1 = add(total1, score);
    }

    for (int i = 0; i < n; ++i) {
        cin >> score;
        total2 = add(total2, score);
    }

    bool oneWins = total1.size() != total2.size()
        ? total1.size() > total2.size()
        : total1 > total2;

    cout << (oneWins ? "one" : "two") << '\n';
}
```

This also handles totals exceeding \(10^{100}\).

