### 3. Guidance controller in JavaScript

```html
<script>
const form = document.querySelector("#registration-form");
const steps = [...form.querySelectorAll("fieldset")];
const help = document.querySelector("#guidance");
const error = document.querySelector("#error");
const back = document.querySelector("#back");
const next = document.querySelector("#next");

let current = 0;
let busy = false;

function activate(index) {
    current = index;

    steps.forEach((step, i) => {
        step.disabled = i !== index;
        step.inert = i !== index;
        step.classList.toggle("active", i === index);
    });

    help.textContent =
        `Step ${index + 1} of ${steps.length}: ` +
        steps[index].dataset.help;

    back.disabled = index === 0;
    next.textContent =
        index === steps.length - 1 ? "Register" : "Next";

    steps[index].querySelector("input").focus();
}

back.addEventListener("click", () => {
    if (!busy && current > 0) activate(current - 1);
});

form.addEventListener("submit", async event => {
    event.preventDefault();
    if (busy) return;

    error.textContent = "";

    const activeInput = steps[current].querySelector("input");
    if (!activeInput.reportValidity()) return;

    if (current < steps.length - 1) {
        activate(current + 1);
        return;
    }

    // Read values explicitly: disabled controls are omitted by FormData.
    const payload = Object.fromEntries(
        steps.map(step => {
            const input = step.querySelector("input");
            return [input.name, input.value];
        })
    );

    busy = true;
    back.disabled = true;
    next.disabled = true;

    try {
        const response = await fetch('@Url.Action("Register", "Registration")', {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "RequestVerificationToken":
                    form.querySelector(
                        '[name="__RequestVerificationToken"]'
                    ).value
            },
            body: JSON.stringify(payload)
        });

        if (!response.ok) {
            const result = await response.json();
            error.textContent = result.error ?? "Check your registration details.";
            return;
        }

        form.hidden = true;
        help.textContent = "Registration completed.";
    } catch {
        error.textContent = "Unable to connect. Please try again.";
    } finally {
        busy = false;
        next.disabled = false;
        back.disabled = current === 0;
    }
});

activate(0);
</script>
```

For production, return **field-keyed validation errors** and activate the relevant field when the server rejects a value.

### 4. ASP.NET Core validation and registration

Use a dedicated request model:

```csharp
public sealed class RegisterRequest
{
    [Required, StringLength(100)]
    public string FullName { get; set; } = "";

    [Required, EmailAddress]
    public string Email { get; set; } = "";

    [Required, MinLength(12)]
    public string Password { get; set; } = "";
}
```

In your MVC controller, validate on the server and use ASP.NET Core Identity:

```csharp
[HttpPost]
[ValidateAntiForgeryToken]
public async Task<IActionResult> Register(
    [FromBody] RegisterRequest? request)
{
    if (request is null || !ModelState.IsValid)
        return BadRequest(new { error = "Invalid registration details." });

    var user = new ApplicationUser
    {
        UserName = request.Email,
        Email = request.Email,
        FullName = request.FullName
    };

    var result = await _userManager.CreateAsync(user, request.Password);

    if (!result.Succeeded)
        return BadRequest(new
        {
            error = string.Join(" ", result.Errors.Select(e => e.Description))
        });

    return Ok();
}
```

This assumes Identity is configured, `_userManager` is injected, and `ApplicationUser` has a `FullName` property. Align the displayed password requirements with the configured Identity policy.

### 5. Lock the rest of the page

Mark unrelated layout regions explicitly:

```html
<header data-outside-guide>...</header>
<nav data-outside-guide>...</nav>
<main><!-- Guided form here --></main>
<footer data-outside-guide>...</footer>
```

During the process:

```javascript
document.querySelectorAll("[data-outside-guide]")
    .forEach(region => region.inert = true);
```

Restore their previous `inert` state when the process ends or is cancelled. Do **not** make an ancestor of the guided form inert; that would disable the form too.

For a reusable framework, move field IDs, instructions, and validation rules into step definitions. Add server-side step state only if ordered completion is a business requirement. Browser guidance alone is not a security boundary.

