## My answer to the prompt

Use a height-constrained flex layout, sticky table-header cells, and a Pinia action that appends pages. After loading a page, check the container again: if it still has empty space, fetch another page rather than waiting for a scroll event that cannot occur.

This example assumes:

- `GET /api/rows?start=0&count=50` returns `{ rows: [...] }`, optionally with `total`.
- Each row has a unique `id`.
- Without `total`, a page shorter than `count` indicates the end of the dataset.

### Pinia store

```js
// src/stores/rows.js
import { defineStore } from 'pinia'

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
    error: null,
  }),

  actions: {
    async loadMore(count = 50) {
      if (this.loading || !this.hasMore) return

      this.loading = true
      this.error = null

      try {
        const start = this.rows.length
        const response = await fetch(
          `/api/rows?start=${start}&count=${count}`
        )

        if (!response.ok) {
          throw new Error(`Request failed: ${response.status}`)
        }

        const data = await response.json()
        if (!Array.isArray(data.rows)) {
          throw new Error('Expected a rows array')
        }

        this.rows.push(...data.rows)

        this.hasMore = data.total != null
          ? data.rows.length > 0 && this.rows.length < data.total
          : data.rows.length === count
      } catch (error) {
        this.error = error.message || 'Could not load rows'
      } finally {
        this.loading = false
      }
    },
  },
})
```

### Infinite-scrolling table

The same check runs on mounting, scrolling, and resizing. The loop keeps loading while the bottom remains near the viewport, stopping on exhaustion or an error.

```vue
<!-- src/components/InfiniteTable.vue -->
<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRowsStore } from '../stores/rows'

const store = useRowsStore()
const container = ref(null)
const threshold = 150

let checking = false
let disposed = false
let resizeObserver

async function ensureFilled() {
  if (checking || disposed) return
  checking = true

  try {
    while (!disposed && store.hasMore && !store.error) {
      // Measure only after Vue has rendered newly appended rows.
      await nextTick()

      const el = container.value
      if (!el || disposed || store.loading) break

      const remaining =
        el.scrollHeight - el.scrollTop - el.clientHeight

      if (remaining > threshold) break

      await store.loadMore(50)
    }
  } finally {
    checking = false
  }
}

function retry() {
  store.error = null
  ensureFilled()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => ensureFilled())
  resizeObserver.observe(container.value)
  ensureFilled()
})

onBeforeUnmount(() => {
  disposed = true
  resizeObserver?.disconnect()
})
</script>

<template>
  <div ref="container" class="table-scroll" @scroll.passive="ensureFilled">
    <table :aria-busy="store.loading">
      <thead>
        <tr>
          <th scope="col">ID</th>
          <th scope="col">Name</th>
          <th scope="col">Email</th>
        </tr>
      </thead>

      <tbody>
        <tr v-for="row in store.rows" :key="row.id">
          <td>{{ row.id }}</td>
          <td>{{ row.name }}</td>
          <td>{{ row.email }}</td>
        </tr>
      </tbody>
    </table>

    <div class="status" aria-live="polite">
      <span v-if="store.loading">Loading…</span>
      <template v-else-if="store.error">
        {{ store.error }}
        <button @click="retry">Retry</button>
      </template>
      <span v-else-if="!store.hasMore">
        {{ store.rows.length ? 'All rows loaded.' : 'No rows found.' }}
      </span>
    </div>
  </div>
</template>

<style scoped>
.table-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}

th,
td {
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid #ddd;
}

thead th {
  position: sticky;
