## My answer to the prompt

Use a height-constrained flex layout, sticky table-header cells, and a Pinia action that appends pages. After each page loads, check whether more rows are needed to fill the scroll area; otherwise, a short first page could leave the user with nothing to scroll.

This example assumes:

- `start` is a zero-based offset.
- The API returns `{ rows: [...] }`, optionally with `total`.
- Without `total`, a page shorter than `count` means the dataset is exhausted.

### 1. Pinia store

```js
// src/stores/rows.js
import { defineStore } from 'pinia'

export const useRowsStore = defineStore('rows', {
  state: () => ({
    rows: [],
    loading: false,
    hasMore: true,
    error: null,
  }),

  actions: {
    async loadMore(count = 40) {
      if (this.loading || !this.hasMore) return

      this.loading = true
      this.error = null

      try {
        const start = this.rows.length
        const response = await fetch(
          `/api/rows?start=${start}&count=${count}`
        )

        if (!response.ok) {
          throw new Error(`Request failed: ${response.status}`)
        }

        const data = await response.json()
        if (!Array.isArray(data.rows)) {
          throw new Error('Invalid API response')
        }

        this.rows.push(...data.rows)

        this.hasMore =
          data.rows.length > 0 &&
          (typeof data.total === 'number'
            ? this.rows.length < data.total
            : data.rows.length === count)
      } catch (error) {
        this.error = error.message || 'Unable to load rows'
      } finally {
        this.loading = false
      }
    },
  },
})
```

### 2. Infinite-scrolling table

The loading loop handles both scrolling and initially filling the available space. A `ResizeObserver` also handles the container becoming taller.

```vue
<!-- src/components/InfiniteTable.vue -->
<script setup>
import { nextTick, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRowsStore } from '../stores/rows'

const store = useRowsStore()
const container = ref(null)

const PAGE_SIZE = 40
const THRESHOLD = 150

let checking = false
let disposed = false
let resizeObserver

function nearBottom() {
  const el = container.value
  return el &&
    el.scrollHeight - el.scrollTop - el.clientHeight <= THRESHOLD
}

async function ensureRows() {
  if (checking || disposed) return
  checking = true

  try {
    await nextTick()

    while (
      !disposed &&
      !store.loading &&
      store.hasMore &&
      !store.error &&
      nearBottom()
    ) {
      await store.loadMore(PAGE_SIZE)
      // Measure only after Vue has rendered the appended rows.
      await nextTick()
    }
  } finally {
    checking = false
  }
}

function retry() {
  store.error = null
  void ensureRows()
}

onMounted(() => {
  resizeObserver = new ResizeObserver(() => void ensureRows())
  resizeObserver.observe(container.value)
  void ensureRows()
})

onBeforeUnmount(() => {
  disposed = true
  resizeObserver?.disconnect()
})
</script>

<template>
  <div
    ref="container"
    class="table-scroll"
    tabindex="0"
    aria-label="Users"
    :aria-busy="store.loading"
    @scroll.passive="ensureRows"
  >
    <table>
      <thead>
        <tr>
          <th scope="col">ID</th>
          <th scope="col">Name</th>
          <th scope="col">Email</th>
        </tr>
      </thead>

      <tbody>
        <tr v-for="row in store.rows" :key="row.id">
          <td>{{ row.id }}</td>
          <td>{{ row.name }}</td>
          <td>{{ row.email }}</td>
        </tr>

        <tr v-if="store.error">
          <td colspan="3" role="alert">
            {{ store.error }}
            <button @click="retry">Retry</button>
          </td>
        </tr>
        <tr v-else-if="store.loading">
          <td colspan="3">Loading…</td>
        </tr>
        <tr v-else-if="!store.hasMore">
          <td colspan="3">
            {{ store.rows.length ? 'All rows loaded' : 'No rows found' }}
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<style scoped>
.table-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}

th,
td {
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid #ddd;
}

th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: white;
}
</style>
```

### 3. Give the table a bounded available height

