## 我的参考答案

使用**扫描线 + 离散化 + 线段树**。

每个矩形产生两个事件：在 `x1` 处加入区间 `[y1,y2)`，在 `x2` 处删除该区间。按横坐标排序后，相邻事件之间的面积为：

\[
\Delta x \times \text{当前被覆盖的 y 轴总长度}
\]

线段树维护离散化后的基本区间。节点覆盖计数大于零时，其覆盖长度就是整个节点区间的长度；否则，叶节点长度为零，内部节点长度为左右孩子之和。

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;
constexpr ll MOD = 1000000007LL;

struct Event {
    int x, y1, y2, delta;
};

vector<int> ys;
int cover[405]{};
ll len[405]{};

// 节点表示离散化下标区间 [l, r)
void pull(int p, int l, int r) {
    if (cover[p] > 0) {
        len[p] = (ll)ys[r] - ys[l];
    } else if (r - l == 1) {
        len[p] = 0;
    } else {
        len[p] = len[p * 2] + len[p * 2 + 1];
    }
}

void update(int p, int l, int r,
            int ql, int qr, int delta) {
    if (qr <= l || r <= ql) return;

    if (ql <= l && r <= qr) {
        cover[p] += delta;
    } else {
        int mid = (l + r) / 2;
        update(p * 2, l, mid, ql, qr, delta);
        update(p * 2 + 1, mid, r, ql, qr, delta);
    }
    pull(p, l, r);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        // 零面积矩形不影响答案
        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    int m = (int)ys.size() - 1;
    ll ans = 0;
    int prevX = events.front().x;

    for (const Event& e : events) {
        // 必须先计算前一个横向条带，再更新当前事件
        ll dx = (ll)e.x - prevX;
        ans = (ans + dx * len[1]) % MOD;

        int l = lower_bound(ys.begin(), ys.end(), e.y1)
                - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2)
                - ys.begin();

        update(1, 0, m, l, r, e.delta);
        prevX = e.x;
    }

    cout << ans << '\n';
    return 0;
}
```

相同横坐标的事件可以逐个处理，因为它们之间的 `dx` 为零。坐标不超过 \(10^9\)，面积乘积使用 `long long` 即可。

- 时间复杂度：\(O(n\log n)\)
- 空间复杂度：\(O(n)\)

