## 一、我的参考答案

采用**扫描线 + 离散化 + 线段树**。

每个矩形产生两个事件：

- 在 `x1` 处，将 `[y1, y2)` 的覆盖次数加一。
- 在 `x2` 处，将 `[y1, y2)` 的覆盖次数减一。

按横坐标处理事件。相邻事件横坐标之间，纵向覆盖情况不变，因此：

\[
\text{新增面积}=(x-\text{上一个横坐标})\times\text{当前纵向覆盖总长度}
\]

离散化所有纵坐标，用线段树维护实际覆盖长度。注意：叶子代表相邻纵坐标之间的区间，而不是一个坐标点。面积为零的矩形可以直接忽略。

以下代码按“先输入 `n`，再输入 `n` 行、每行四个空白分隔整数”的格式读取：

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

struct Event {
    ll x, y1, y2;
    int delta;
};

struct SegmentTree {
    vector<ll> ys, len;
    vector<int> cover;
    int n;

    explicit SegmentTree(const vector<ll>& y)
        : ys(y), n((int)y.size() - 1) {
        len.assign(4 * n + 4, 0);
        cover.assign(4 * n + 4, 0);
    }

    void pull(int p, int l, int r) {
        if (cover[p] > 0) {
            len[p] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[p] = 0;
        } else {
            len[p] = len[p * 2] + len[p * 2 + 1];
        }
    }

    // 节点表示 [l, r)，更新区间为 [ql, qr)
    void update(int p, int l, int r, int ql, int qr, int delta) {
        if (qr <= l || r <= ql) return;

        if (ql <= l && r <= qr) {
            cover[p] += delta;
        } else {
            int mid = (l + r) / 2;
            update(p * 2, l, mid, ql, qr, delta);
            update(p * 2 + 1, mid, r, ql, qr, delta);
        }
        pull(p, l, r);
    }

    void update(int l, int r, int delta) {
        if (l < r) update(1, 0, n, l, r, delta);
    }

    ll coveredLength() const {
        return len[1];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    vector<ll> ys;

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 == x2 || y1 == y2) continue;

        events.push_back({x1, y1, y2, 1});
        events.push_back({x2, y1, y2, -1});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (events.empty()) {
        cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    sort(events.begin(), events.end(),
         [](const Event& a, const Event& b) {
             return a.x < b.x;
         });

    SegmentTree seg(ys);
    ll ans = 0;
    ll prevX = events.front().x;

    size_t i = 0;
    while (i < events.size()) {
        ll x = events[i].x;
        ans = (ans + (x - prevX) * seg.coveredLength()) % MOD;

        while (i < events.size() && events[i].x == x) {
            int l = lower_bound(ys.begin(), ys.end(), events[i].y1)
                    - ys.begin();
            int r = lower_bound(ys.begin(), ys.end(), events[i].y2)
                    - ys.begin();
            seg.update(l, r, events[i].delta);
            ++i;
        }
        prevX = x;
    }

    cout << ans << '\n';
    return 0;
}
```

**正确性要点：**覆盖次数大于零时，节点对应区间全部被覆盖；否则，覆盖长度等于两个子区间覆盖长度之和。这样根节点始终记录纵向并集长度。扫描线将平面划分成互不重叠的竖条，逐条累加即可得到矩形并集面积。

**复杂度：**时间 `O(n log n)`，空间 `O(n)`。坐标范围下，每条面积不超过 `10^18`，使用 `long long` 安全。

