// user-api.ts
import type { APIRequestContext } from '@playwright/test';

export interface CreateUserInput {
  username: string;
  password: string;
}

export interface Credentials {
  username: string;
  password: string;
}

export interface ProvisionedUser extends Credentials {
  id: string;
}

// The provisioning workflow depends only on the operations it needs.
export interface UserSetupApi {
  create(input: CreateUserInput): Promise<{ id: string }>;
  setPermissions(id: string, role: string): Promise<Credentials>;
}

export interface UserCleanupApi {
  remove(id: string): Promise<void>;
}

export class HttpUserApi implements UserSetupApi, UserCleanupApi {
  constructor(private readonly request: APIRequestContext) {}

  async create(input: CreateUserInput): Promise<{ id: string }> {
    const response = await this.request.post('/users/v2/create', {
      data: input,
    });

    if (response.status() !== 201) {
      throw new Error(`Create user failed: HTTP ${response.status()}`);
    }

    const body: unknown = await response.json();
    if (
      typeof body !== 'object' ||
      body === null ||
      !('id' in body) ||
      typeof body.id !== 'string'
    ) {
      throw new Error('Create user returned an invalid id');
    }

    return { id: body.id };
  }

  async setPermissions(id: string, role: string): Promise<Credentials> {
    const response = await this.request.post('/users/v2/permissions', {
      data: { id, role },
    });

    if (response.status() !== 200) {
      throw new Error(`Set permissions failed: HTTP ${response.status()}`);
    }

    const body: unknown = await response.json();
    if (
      typeof body !== 'object' ||
      body === null ||
      !('username' in body) ||
      typeof body.username !== 'string' ||
      !('password' in body) ||
      typeof body.password !== 'string'
    ) {
      throw new Error('Permissions response did not contain valid credentials');
    }

    return { username: body.username, password: body.password };
  }

  async remove(id: string): Promise<void> {
    // Assumption: replace with your actual deletion endpoint/contract.
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // Already deleted by a CRUD test is an acceptable cleanup outcome.
    if (![204, 404].includes(response.status())) {
      throw new Error(`Delete user failed: HTTP ${response.status()}`);
    }
  }
}
