import type { APIRequestContext, APIResponse } from '@playwright/test';

export interface CreateUserInput {
  username: string;
  password: string;
}

export interface Permissions {
  role: string;
  privileges: string[];
}

export interface Credentials {
  username: string;
  password: string;
}

export interface CreatedUser {
  id: string;
}

export interface ProvisionedUser extends Credentials {
  id: string;
}

// Provisioning does not need to depend on unrelated read/update operations.
export interface UserSetupApi {
  create(input: CreateUserInput): Promise<CreatedUser>;
  setPermissions(id: string, input: Permissions): Promise<Credentials>;
}

export interface UserCleanupApi {
  delete(id: string): Promise<void>;
}

export class HttpUserApi implements UserSetupApi, UserCleanupApi {
  constructor(private readonly request: APIRequestContext) {}

  async create(input: CreateUserInput): Promise<CreatedUser> {
    const response = await this.request.post('/users/v2/create', {
      data: input,
    });

    await this.requireStatus(response, 201);

    const body: unknown = await response.json();

    if (
      typeof body !== 'object' ||
      body === null ||
      !('id' in body) ||
      typeof body.id !== 'string' ||
      body.id.length === 0
    ) {
      throw new Error('Create-user response must contain a nonempty string id');
    }

    return { id: body.id };
  }

  async setPermissions(
    id: string,
    input: Permissions,
  ): Promise<Credentials> {
    const response = await this.request.post('/users/v2/permissions', {
      data: { ...input, id },
    });

    await this.requireStatus(response, 200);

    const body: unknown = await response.json();

    if (
      typeof body !== 'object' ||
      body === null ||
      !('username' in body) ||
      !('password' in body) ||
      typeof body.username !== 'string' ||
      typeof body.password !== 'string'
    ) {
      throw new Error('Permissions response must contain credentials');
    }

    return { username: body.username, password: body.password };
  }

  async delete(id: string): Promise<void> {
    // Assumed endpoint: replace with your actual deletion contract.
    const response = await this.request.delete(
      `/users/v2/${encodeURIComponent(id)}`,
    );

    // An already-deleted user requires no further cleanup.
    if (response.status() === 404) return;

    await this.requireStatus(response, 204);
  }

  private async requireStatus(
    response: APIResponse,
    expected: number,
  ): Promise<void> {
    if (response.status() !== expected) {
      // Avoid logging response bodies that might contain credentials.
      throw new Error(
        `${response.url()}: expected HTTP ${expected}, got ${response.status()}`,
      );
    }
  }
}
