        provisioner.createAdmin({
          username: `admin-${randomUUID()}`,
          password: `Test-${randomUUID()}!`,
        }),
      );
    } finally {
      // Attempt every deletion, even if one fails.
      const results = await Promise.allSettled(
        [...createdIds].map(id => api.delete(id)),
      );

      const failures = results.filter(result => result.status === 'rejected');

      if (failures.length > 0) {
        throw new Error(`Cleanup failed for ${failures.length} test user(s)`);
      }
    }
  },
});

export { expect };
```

