```java
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.print("请输入台阶数 n：");

            if (!scanner.hasNextInt()) {
                System.out.println("请输入 int 范围内的非负整数。");
                return;
            }

            int n = scanner.nextInt();
            if (n < 0) {
                System.out.println("台阶数不能为负数。");
                return;
            }

            System.out.println("总共有 " + countWays(n) + " 种走法。");
            System.out.println("所有走法如下（每个数字表示该次走几级）：");
            listWays(n, new ArrayList<>());
        }
    }

    // f(0) = 1，f(1) = 1
    // f(n) = f(n - 1) + f(n - 2)
    private static BigInteger countWays(int n) {
        if (n <= 1) {
            return BigInteger.ONE;
        }

        BigInteger previous = BigInteger.ONE;
        BigInteger current = BigInteger.ONE;

        for (int i = 2; i <= n; i++) {
            BigInteger next = previous.add(current);
            previous = current;
            current = next;
        }
        return current;
    }

    private static void listWays(int remaining, List<Integer> path) {
        if (remaining == 0) {
            System.out.println(path);
            return;
        }

        for (int step = 1; step <= 2 && step <= remaining; step++) {
            path.add(step);
            listWays(remaining - step, path);
            path.remove(path.size() - 1); // 回溯
        }
    }
}
```

输入 `4` 时，输出的走法为：

```text
[1, 1, 1, 1]
[1, 1, 2]
[1, 2, 1]
[2, 1, 1]
[2, 2]
```

共 **5** 种。

约定 `n = 0` 时有一种方法，即不走任何一步，输出 `[]`。走法数量呈指数增长，列举仅适合较小的 `n`；`BigInteger` 能避免计数溢出，但不能消除枚举耗时和递归深度限制。

