        for (ll i = 1; i * i <= d; ++i) {
            if (d % i != 0) continue;

            ll j = d / i;
            if (i >= 2 && check(a, b, c, i))
                ++ans;
            if (j != i && j >= 2 && check(a, b, c, j))
