    [~, maxEnergyIdx] = max(fval(:,2));

    candidateIdx = find(fval(:,1) <= 1.1 * minError + 1e-10);
    [~, localIdx] = min(fval(candidateIdx,2));
    balancedIdx = candidateIdx(localIdx);

    labels = {'最高能耗代理指标点', '最低误差点', '均衡点'};
    indices = [maxEnergyIdx, minErrorIdx, balancedIdx];

    jointNames = {'Joint1','Joint2','Joint3', ...
                  'Joint4','Joint5','Joint6'};

    for k = 1:numel(indices)
        idx = indices(k);

        fprintf('\n%s - 关节角度（度）：\n', labels{k});
        disp(array2table(rad2deg(x(idx,:)), ...
            'VariableNames', jointNames));

